def split_fields(text: str) -> list[str]:
    fields = []
    current = ""
    escaped = False
    for ch in text:
        if escaped:
            if ch == "," or ch == "\\":
                current = current + ch
            else:
                raise ValueError("invalid escape")
            escaped = False
        elif ch == "\\":
            escaped = True
        elif ch == ",":
            fields.append(current)
            current = ""
        else:
            current = current + ch
    if escaped:
        raise ValueError("dangling backslash")
    fields.append(current)
    return fields

